 useEffect(()=>{if(token&&user){loadWorkspace(user,token);const now=new Date();loadTimetables(`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`)}},[token,user]);
 useEffect(()=>{const onKey=e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setSearchOpen(true)}if(e.key==='Escape'){setSearchOpen(false);setDrawer(false)}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);
 const login=async(email,password,role)=>{setLoading(true);setError('');try{const result=await api('/auth/login',{method:'POST',token:null,body:{email,password,role}});sessionStorage.setItem('chrono-token',result.token);sessionStorage.setItem('chrono-user',JSON.stringify(result.user));setToken(result.token);setUser(result.user);navigate('/');}catch(e){setError(e.message)}finally{setLoading(false)}};
 const isFaculty=user?.role==='faculty';
